def comps(g,c):
 H,W=len(g),len(g[0]); pts=set(coords(g,c)); out=[]
 while pts:
  stack=[pts.pop()]; comp=set(stack)
  while stack:
   r,col=stack.pop()
   for dr in [-1,0,1]:
    for dc in [-1,0,1]:
     q=(r+dr,col+dc)
     if q in pts: pts.remove(q);comp.add(q);stack.append(q)
  out.append(comp)
 return out

def diamond(r0,c0,R,H,W):
 return {(r,c) for r in range(max(0,r0-R),min(H-1,r0+R)+1) for c in [c0-(R-abs(r-r0)),c0+(R-abs(r-r0))] if 0<=c<W}
def fit_diamond(S,H,W):
 fits=[]
 # centers inferred broad range
 for r0 in range(-15,H+15):
  for c0 in range(-15,W+15):
   for R in range(0,16):
    if diamond(r0,c0,R,H,W)==S: fits.append((R,r0,c0))
 return sorted(fits)
