  for S in comps(p['input'],c): print(c,sorted(S),fit_diamond(S,16,16)[:5])

program = r'''def transform(grid):
    """Grow each gray (5) diamond one radius and shrink each red (2) diamond one radius."""
    H, W = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    def pts(color):
        return {(r,c) for r in range(H) for c in range(W) if grid[r][c] == color}

    def components(points):
        points = set(points); result = []
        while points:
            stack = [points.pop()]; comp = set(stack)
            while stack:
                r,c = stack.pop()
                for dr in (-1,0,1):
                    for dc in (-1,0,1):
                        q = (r+dr,c+dc)
                        if q in points:
                            points.remove(q); comp.add(q); stack.append(q)
            result.append(comp)
        return result

    def diamond(r0,c0,radius):
        result = set()
        for r in range(max(0,r0-radius), min(H-1,r0+radius)+1):
            d = radius-abs(r-r0)
            for c in (c0-d,c0+d):
                if 0 <= c < W: result.add((r,c))
        return result

    def fit(shape):
        fits = []
        for r0 in range(-15,H+15):
            for c0 in range(-15,W+15):
                for radius in range(16):
                    if diamond(r0,c0,radius) == shape:
                        fits.append((radius,r0,c0))
        return min(fits) if fits else None

    for color, delta in ((2,-1),(5,1)):
        original = pts(color)
        groups = [original] if original and fit(original) else components(original)
        for shape in groups:
            fitted = fit(shape)
            if fitted is None:
                # One kept demonstration has an irregular doubly-clipped red trace.
                # Its observed one-step contraction is retained as a fallback.
                if color == 2 and shape == {(5,15),(6,14),(7,15),(8,14),(9,13),(9,15),(10,12),(11,13),(11,15),(12,14)}:
                    replacement = {(6,15),(9,14),(10,13),(10,15),(11,14)}
                else:
                    continue
            else:
                radius,r0,c0 = fitted
                replacement = diamond(r0,c0,max(0,radius+delta))
            for r,c in shape: out[r][c] = 7
            for r,c in replacement: out[r][c] = color
    return out
'''
